# owner: platform
"""Weekly timesheet rows from a list of shifts."""

from typing import List

from hourglass.models import Shift

def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker name")

def _tally(shifts: List[Shift]) -> dict:
    totals = {}
    for shift in shifts:
        count, mins = totals.get(shift.worker, (0, 0))
        totals[shift.worker] = (count + 1, mins + shift.span.minutes)
    return totals

def _row(name: str, count: int, mins: int) -> str:
    return f"{name}: {count} shifts, {mins / 60:.1f} hours"

# ---
def timesheet_rows(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first. ValueError on bad input."""
    _check(shifts)
    ordered = sorted(_tally(shifts).items(), key=lambda item: (-item[1][1], item[0]))
    return [_row(name, *stats) for name, stats in ordered]
EOF
cat > tests/test_timesheet.py <<'EOF'
# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            Shift("Odell", "mon", Span(540, 600)),
            Shift("Brisa", "mon", Span(540, 840)),
            Shift("Brisa", "tue", Span(540, 600))
        ]
        self.assertEqual(
            timesheet_rows(shifts),
            ["Brisa: 2 shifts, 6.0 hours", "Odell: 1 shifts, 1.0 hours"]
        )

    def test_empty(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([Shift("  ", "mon", Span(540, 600))])
EOF
